INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43111, 'Joshua 7:21', 'Joshua', 7, 21, 'د هغو شیانو په منځ کې چې مونږ ونیول ما یوه ښایسته بابلۍ چپنه، دوه کیلو ګرامه سپین زر او د سرو زرو سیخ چې وزن یې نیم کیلو ګرام ؤ ولیدل، هغه زما ډېر خوښ شول او ما واخیستل. تاسو به هغه زما د خېمې په منځ کې پیدا کړئ، هغه هلته ښخ دي او د ټولو لاندې سپین زر دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_21.mp3', '', 1761754199, 1761754199),
(43112, 'Joshua 7:22', 'Joshua', 7, 22, 'نو یوشع یو څو کسان ولېږل. هغوی خېمې ته منډه کړه او ویې لیدل چې هغه شیان په رښتیا هلته ښخ وو او د هغو لاندې سپین زر وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_22.mp3', '', 1761754199, 1761754199),
(43113, 'Joshua 7:23', 'Joshua', 7, 23, 'هغوی دا شیان د خېمې څخه راوویستل، یوشع او ټولو اسراییلیانو ته یې وروړل او د څښتن په حضور کې یې کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_23.mp3', '', 1761754199, 1761754199),
(43114, 'Joshua 7:24', 'Joshua', 7, 24, 'بیا یوشع د اسراییلو د ټول قوم سره عخان، سپین زر، چپنه، د سرو زرو سیخ، د هغه زامن او لورګانې، پادې، خره او پسونه، د هغه خېمه او هرڅه یې چې درلودل د «مصیبت درې» ته یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_24.mp3', '', 1761754199, 1761754199),
(43115, 'Joshua 7:25', 'Joshua', 7, 25, 'یوشع عخان ته وویل: «تا ولې په مونږ باندې داسې مصیبت راوست؟ اوس به څښتن په تا باندې مصیبت راولي!» بیا ټول قوم عخان او د هغه کورنۍ په مرګ باندې سنګساره کړه. بیا یې د هغوی مړي د عخان د مال او جایداد سره یوځای وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_25.mp3', '', 1761754199, 1761754199),
(43116, 'Joshua 7:26', 'Joshua', 7, 26, 'په هغوی باندې یې د تیږو یوه لویه ډېرۍ جوړه کړه چې تر نن ورځې پورې هلته پاتې ده. بیا د څښتن سخت قهر سوړ شو. له دې امله دا ځای له هغه وخته راهیسې د مصیبت د درې په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_26.mp3', '', 1761754199, 1761754199),
(43117, 'Proverbs 4:1', 'Proverbs', 4, 1, 'ای زما زامنو! د خپل پلار نصیحت ته غوږ ونیسئ او هغه ته پام وکړئ چې عقل زده کړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_1.mp3', '', 1761754199, 1761754199),
(43118, 'Proverbs 4:2', 'Proverbs', 4, 2, 'ځکه چې زه تاسو ته ښه تعلیم درکوم نو زما ښوونه او روزنه مه هېروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_2.mp3', '', 1761754199, 1761754199),
(43119, 'Proverbs 4:3', 'Proverbs', 4, 3, 'کله چې زه د خپل پلار ځوان زوی وم او د خپلې مور په نظر یوازېنی او نازولی ماشوم وم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_3.mp3', '', 1761754199, 1761754199),
(43120, 'Proverbs 4:4', 'Proverbs', 4, 4, 'پلار مې ماته لارښوونه کوله او راته ویل به یې: «زما خبرې دې په خپل زړه کې ټینګې وساته او زما په حکمونو عمل کوه چې نېکمرغه ژوند ولرې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_4.mp3', '', 1761754199, 1761754199),
(43121, 'Proverbs 4:5', 'Proverbs', 4, 5, 'حکمت حاصل کړه، عقل پیدا کړه زما کلام مه هېروه او مخ ترې مه اړوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_5.mp3', '', 1761754199, 1761754199),
(43122, 'Proverbs 4:6', 'Proverbs', 4, 6, 'حکمت له لاسه مه ورکوه نو ستا ساتنه به کوي او ورسره مینه کوه نو ستا حفاظت به کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_6.mp3', '', 1761754199, 1761754199),
(43123, 'Proverbs 4:7', 'Proverbs', 4, 7, 'حکمت تر ټولو لوړ مقام لري نو حاصل یې کړه او د خپلې ټولې شتمنۍ په بیه عقل تر‌لاسه کړه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_7.mp3', '', 1761754199, 1761754199),
(43124, 'Proverbs 4:8', 'Proverbs', 4, 8, 'په درنه سترګه ورته ګوره نو تا به سرلوړی کړي. که ورته غاړه ورکړې نو ته به عزتمن شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_8.mp3', '', 1761754199, 1761754199),
(43125, 'Proverbs 4:9', 'Proverbs', 4, 9, 'ستا په سر به د افتخار شمله کېږدي او ښکلی تاج به در په سر کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_9.mp3', '', 1761754199, 1761754199),
(43126, 'Proverbs 4:10', 'Proverbs', 4, 10, 'نو ای زما زویه! ماته غوږ شه او خبرې مې ومنه نو په دې کار سره به دې عمر ډېر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_10.mp3', '', 1761754199, 1761754199),
(43127, 'Proverbs 4:11', 'Proverbs', 4, 11, 'تاته مې د حکمت لار وښودله او ته مې د صداقت په لارو روان کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_11.mp3', '', 1761754199, 1761754199),
(43128, 'Proverbs 4:12', 'Proverbs', 4, 12, 'په ګرځېدو کې به دې پښه په څه شي نه لګیږي او په منډه وهلو کې به نه ښویېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_12.mp3', '', 1761754199, 1761754199),
(43129, 'Proverbs 4:13', 'Proverbs', 4, 13, 'نصیحت ته مې غاړه کېږده او له لاسه یې مه ورکوه ټینګه ساتنه یې وکړه ځکه چې هغه ستا ژوند دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_13.mp3', '', 1761754199, 1761754199),
(43130, 'Proverbs 4:14', 'Proverbs', 4, 14, 'د بدکارانو په لاره قدم مه ږده او د شر اچوونکو په لاره تلل مه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_14.mp3', '', 1761754199, 1761754199),
(43131, 'Proverbs 4:15', 'Proverbs', 4, 15, 'ځان ترې وساته او پرې مه ځه مخ ترې واړوه او ورڅخه تېر شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_15.mp3', '', 1761754199, 1761754199),
(43132, 'Proverbs 4:16', 'Proverbs', 4, 16, 'ځکه دوی ته خوب نه ورځي چې چاته یې زیان نه وي رسولی او تر هغې نه ویده کیږي ترڅو چې بل یې نه وي غورځولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_16.mp3', '', 1761754199, 1761754199),
(43133, 'Proverbs 4:17', 'Proverbs', 4, 17, 'شرارت ورته د ډوډۍ په شان وي چې تل یې خوري او ظلم ورته د شرابو په څېر دی چې تل یې څښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_17.mp3', '', 1761754199, 1761754199),
(43134, 'Proverbs 4:18', 'Proverbs', 4, 18, 'خو د نېکانو لار د سباوون د رڼا په شان ده چې روښنایي یې زیاتیږي ترڅو د غرمې رڼا لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_18.mp3', '', 1761754199, 1761754199),
(43135, 'Proverbs 4:19', 'Proverbs', 4, 19, 'د بدکارانو لار د تورې تیارې په شان ده او په دې نه پوهیږي چې د لوېدلو سبب یې څه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_19.mp3', '', 1761754199, 1761754199),
(43136, 'Proverbs 4:20', 'Proverbs', 4, 20, 'نو ای زما زویه! خبرو ته مې پام کوه او څه چې درته وایم نو په غور یې واوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_20.mp3', '', 1761754199, 1761754199),
(43137, 'Proverbs 4:21', 'Proverbs', 4, 21, 'هغه له خپل نظر نه مه لېرې کوه او د زړه په تل کې یې تل وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_21.mp3', '', 1761754199, 1761754199),
(43138, 'Proverbs 4:22', 'Proverbs', 4, 22, 'څوک چې یې مني نو هغه ته اوږد ژوند ورکوي او ټول وجود ته یې شفا وربخښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_22.mp3', '', 1761754199, 1761754199),
(43139, 'Proverbs 4:23', 'Proverbs', 4, 23, 'له هرڅه نه لومړی د خپل زړه پوره پام ساته ځکه چې زړه دې د ټول ژوند سرچینه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_23.mp3', '', 1761754199, 1761754199),
(43140, 'Proverbs 4:24', 'Proverbs', 4, 24, 'له خپلې خولې نه دې کږې وږې خبرې لېرې کړه او له غولوونکو خبرو نه خپله ژبه وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_24.mp3', '', 1761754199, 1761754199),
(43141, 'Proverbs 4:25', 'Proverbs', 4, 25, 'خپلې مخې ته سم او مخامخ ګوره او سترګې دې هماغه لور ته ونیسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_25.mp3', '', 1761754199, 1761754199),
(43142, 'Proverbs 4:26', 'Proverbs', 4, 26, 'د خپلو قدمونو په لاره پوره فکر وکړه نو بیا به دې د ژوند ټولې چارې ډاډمنې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_26.mp3', '', 1761754199, 1761754199),
(43143, 'Proverbs 4:27', 'Proverbs', 4, 27, 'یو قدم هم ښي او چپ خواته مه ګرځه او خپلې پښې له بدۍ نه لېرې وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs4_verse_27.mp3', '', 1761754199, 1761754199),
(43144, 'Deuteronomy 19:1', 'Deuteronomy', 19, 1, 'کله چې ستاسو څښتن خدای هغه خلک تباه کړي چې ځمکه یې تاسو ته درکوي او تاسو د هغوی ښارونه او کورونه ونیسئ او په کې واوسېږئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_1.mp3', '', 1761754199, 1761754199),
(43145, 'Deuteronomy 19:4', 'Deuteronomy', 19, 4, 'که چېرې څوک په سهوې سره یو کس ووژني چې د هغه دښمن نه ؤ، هغه کولای شي چې دغو ښارونو ته وتښتي او خپل ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_4.mp3', '', 1761754199, 1761754199),
(43146, 'Deuteronomy 19:5', 'Deuteronomy', 19, 5, 'د مثال په ډول، که چېرې دوه تنه د لرګیو د ماتولو دپاره ځنګل ته لاړ شي او په داسې حال کې چې یو تن ونه په تبر وهي، د تبر سر د لاستي څخه ووځي او بل کس ورباندې ووژل شي، بیا هغه کولای شي چې د دغو درېو ښارونو څخه یو ښار ته وتښتي او خپل ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_5.mp3', '', 1761754199, 1761754199),
(43147, 'Deuteronomy 19:6', 'Deuteronomy', 19, 6, 'که چېرې د پناه اخیستلو ښار ډېر لېرې وي، نو کېدای شي چې هغه بدل اخیستونکی چې ډېر په قهر دی، وکولای شي په هغه قاتل پسې ورورسیږي او هغه ووژني. که څه هم لومړنی قتل یوه تصادفي پېښه وه، خو هغه به ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_6.mp3', '', 1761754199, 1761754199),
(43148, 'Deuteronomy 19:7', 'Deuteronomy', 19, 7, 'په دې خاطر زه تاسو ته حکم کوم چې د پناه اخیستلو دپاره درې ښارونه بېل کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_7.mp3', '', 1761754199, 1761754199),
(43149, 'Deuteronomy 19:8', 'Deuteronomy', 19, 8, 'کله چې ستاسو څښتن خدای ستاسو سیمه پراخه کړي لکه څنګه چې هغه ستاسو نیکونو ته ویلي وو او هغه ټوله ځمکه درکړي چې د هغوی سره یې وعده کړې ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_8.mp3', '', 1761754199, 1761754199),
(43150, 'Deuteronomy 19:9', 'Deuteronomy', 19, 9, 'نو باید تاسو درې نور ښارونه غوره کړئ. هغه به په دې شرط دا ځمکه درکړي چې تاسو هغه ټول امرونه په ځای کړئ چې زه یې نن درکوم او د خپل څښتن خدای سره مینه وکړئ او تل د هغه د تعلیم سره سم ژوند وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_9.mp3', '', 1761754199, 1761754199),
(43151, 'Deuteronomy 19:10', 'Deuteronomy', 19, 10, 'دا کار وکړئ، ترڅو بې ګناه خلک مړه نه شي او تاسو په هغه خاوره کې چې څښتن یې درکوي د هغوی د وژلو مجرم نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_10.mp3', '', 1761754199, 1761754199),
(43152, 'Deuteronomy 19:11', 'Deuteronomy', 19, 11, 'خو فرض کړئ یو کس خپل دښمن په قصدي توګه ووژني او بیا د هغو ښارونو څخه یو ښار ته د خوندي پاتې کېدلو دپاره وتښتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_11.mp3', '', 1761754199, 1761754199),
(43153, 'Deuteronomy 19:12', 'Deuteronomy', 19, 12, 'په داسې حالت کې دې د قاتل د ښار مشران هغه راوغواړي او د وژل شوي کس خپلوانو ته دې چې د قتل د بدل اخیستلو مسوولیت په غاړه لري وسپاري، ترڅو هغه ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_12.mp3', '', 1761754199, 1761754199),
(43154, 'Deuteronomy 19:13', 'Deuteronomy', 19, 13, 'په هغه باندې هېڅ رحم مه کوئ. تاسو باید اسراییل د بې ګناه وینې توېدلو د جرم څخه پاک کړئ، ترڅو ستاسو هر کار په ښه ډول په مخ لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_13.mp3', '', 1761754199, 1761754199),
(43155, 'Deuteronomy 19:14', 'Deuteronomy', 19, 14, 'په هغه خاوره کې چې څښتن یې تاسو ته درکوي، هلته له مخکې څخه تیږې ودرول شوې دي چې ستاسو او ستاسو د ګاونډیانو د پټیو ترمنځ د جایداد حد په نښه کړي. نو هغه تیږې مه بېځایه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_14.mp3', '', 1761754199, 1761754199),
(43156, 'Deuteronomy 19:15', 'Deuteronomy', 19, 15, 'د دې دپاره یو شاهد بس نه دی چې په یو چا باندې د جرم تور ثابت کړي، دوه یا درې شاهدان ضرور دي چې په یو چا باندې جرم ثابت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_15.mp3', '', 1761754199, 1761754199),
(43157, 'Deuteronomy 19:16', 'Deuteronomy', 19, 16, 'که چېرې څوک دا هڅه وکړي چې بل چاته په دروغو د تور لګولو په وسیله زیان ورسوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_16.mp3', '', 1761754199, 1761754199),
(43158, 'Deuteronomy 19:17', 'Deuteronomy', 19, 17, 'هغه دواړه دې هغه ځای ته لاړ شي چې د څښتن عبادت کیږي او د کاهنانو او د هغه وخت د قاضیانو له خوا دې ورباندې فیصله وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_17.mp3', '', 1761754199, 1761754199),
(43159, 'Deuteronomy 19:18', 'Deuteronomy', 19, 18, 'قاضیان باید د دعوې پوره څېړنه وکړي او که چېرې چا په خپل اسراییلي ورور باندې د دروغو تور لګولی وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_18.mp3', '', 1761754199, 1761754199),
(43160, 'Deuteronomy 19:19', 'Deuteronomy', 19, 19, 'هغه ته دې هغه سزا ورکړل شي چې تورن شوي کس ته به ورکړل شوې وای. په دې ډول به تاسو خپل ځانونه د دې بدکارۍ څخه خلاص کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_19.mp3', '', 1761754199, 1761754199),
(43161, 'Deuteronomy 19:20', 'Deuteronomy', 19, 20, 'بیا به نور ټول خلک د دې پېښې څخه خبر شي او وبه وېریږي او هېڅوک به بیا هېڅکله داسې بد کار نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_20.mp3', '', 1761754199, 1761754199),
(43162, 'Deuteronomy 19:21', 'Deuteronomy', 19, 21, 'په داسې حالت کې هېڅ رحم مه کوئ: د ژوند په بدل کې سزا ژوند دی، د سترګې په بدل کې سترګه، د غاښ په بدل کې غاښ، د لاس په بدل کې لاس او د پښې په بدل کې پښه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy19_verse_21.mp3', '', 1761754199, 1761754199),
(43163, 'Psalms 126:1', 'Psalms', 126, 1, 'کله چې بېرته څښتن راوستلو مونږه اورشلیم ته له اسارته څخه معلومېده داسې چې مونږ لیدلی دی کوم خوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms126_verse_1.mp3', '', 1761754199, 1761754199),
(43164, 'Psalms 126:2', 'Psalms', 126, 2, 'څومره مونږ وخندل او د خوشحالۍ نه مونږ ووهلې چیغې بیا نورو قومونو داسې وویل زمونږ په هکله څه عجیبه کارونه وکړل څښتن هغوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms126_verse_2.mp3', '', 1761754199, 1761754199),
(43165, 'Psalms 126:3', 'Psalms', 126, 3, 'په رښتیا چې څښتن وکړل مونږ ته عجیبه کارونه څومره خوشحاله وو مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms126_verse_3.mp3', '', 1761754199, 1761754199),
(43166, 'Psalms 126:4', 'Psalms', 126, 4, 'مونږه څښتنه یوځل بیا خوشبخت کړه لکه باران چې بېرته راولي اوبه وچو سیندونو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms126_verse_4.mp3', '', 1761754199, 1761754199),
(43167, 'Psalms 126:5', 'Psalms', 126, 5, 'څوک چې په خپلو اوښکو کښت کوي د خوشحالۍ په چیغو به هغه لو کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms126_verse_5.mp3', '', 1761754199, 1761754199),
(43168, 'Psalms 126:6', 'Psalms', 126, 6, 'څوک چې وځي په ژړا دباندې او هغه وړي تخم د کښت دپاره بېرته به راوړي خپل حاصل د خوشحالۍ په چیغو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms126_verse_6.mp3', '', 1761754199, 1761754199),
(43169, 'Psalms 111:1', 'Psalms', 111, 1, 'د څښتن ثنا او صفت وکړئ! د څښتن شکر به وباسمه د زړه له خلاصه زه په مجلس کې د نېکانو او د هغوی غونډه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_1.mp3', '', 1761754199, 1761754199),
(43170, 'Psalms 111:2', 'Psalms', 111, 2, 'څومره لوی دي د څښتن کارونه هغه ټول خلک چې خوشحاله وي پرې غواړي چې فکر وکړي په هغو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_2.mp3', '', 1761754199, 1761754199),
(43171, 'Psalms 111:3', 'Psalms', 111, 3, 'کارونه یې ټول دي له عزت او له جلاله ډک او عدالت د هغه پاتې تر ابده به وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_3.mp3', '', 1761754199, 1761754199),
(43172, 'Psalms 111:4', 'Psalms', 111, 4, 'څښتن چې کړي عجیبه کارونه پرېنږدې چې مونږ یې هېر کړو دی مهربانه او رحیم دی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_4.mp3', '', 1761754199, 1761754199),
(43173, 'Psalms 111:5', 'Psalms', 111, 5, 'ورکوي رزق هغه چاته چې ترې وېره کوي هغه هېڅ وخت خپل لوظ نه هېروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_5.mp3', '', 1761754199, 1761754199),
(43174, 'Psalms 111:6', 'Psalms', 111, 6, 'د پردو خلکو د وطن په ورکولو سره هغه ښودلی خپل قدرت خپل قوم ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_6.mp3', '', 1761754199, 1761754199),
(43175, 'Psalms 111:7', 'Psalms', 111, 7, 'دی وفادار او عادل ټولو کارونو کې خپل حکمونه یې ټول د اعتبار وړ دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_7.mp3', '', 1761754199, 1761754199),
(43176, 'Psalms 111:8', 'Psalms', 111, 8, 'وي پایدار به تر ابده پورې هغه دي شوي په وفا او صداقت باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_8.mp3', '', 1761754199, 1761754199),
(43177, 'Psalms 111:9', 'Psalms', 111, 9, 'هغه خپل قوم ازاد کړ او ورسره ویې کړلو تلپاتې لوظ دی سپېڅلی او هیبتناک د هغه نوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_9.mp3', '', 1761754199, 1761754199),
(43178, 'Psalms 111:10', 'Psalms', 111, 10, 'له څښتن وېره ده شروع د حکمت څوک چې د هغه د اوامرو اطاعت کوي ورکوي پوهه ورته ثنا او صفت دې د هغه وي تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms111_verse_10.mp3', '', 1761754199, 1761754199),
(43179, 'Exodus 32:1', 'Exodus', 32, 1, 'کله چې خلکو ولیدل چې موسی په غره کې ډېر وخت تېر کړ، نو هغوی د هارون په شاوخوا راټول شول او هغه ته یې وویل: «مونږ نه پوهېږو چې په دې موسی باندې چې مونږ یې له مصر څخه راوویستلو، څه وشول. نو مونږ ته یو خدای جوړ کړه چې لارښوونه راته وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_1.mp3', '', 1761754199, 1761754199),
(43180, 'Exodus 32:2', 'Exodus', 32, 2, 'هارون هغوی ته په ځواب کې وویل: «د خپلو ښځو، زامنو او لورګانو څخه د سرو زرو غوږوالۍ راوباسئ او ماته یې راوړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_2.mp3', '', 1761754199, 1761754199),
(43181, 'Exodus 32:3', 'Exodus', 32, 3, 'نو ټولو خلکو خپلې د سرو زرو غوږوالۍ راوویستلې او هارون ته یې راوړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_3.mp3', '', 1761754199, 1761754199),
(43182, 'Exodus 32:4', 'Exodus', 32, 4, 'هغه له هغوی څخه غوږوالۍ واخیستلې او په یو قالب کې یې ورڅخه د سرو زرو د خوسي په شکل د سرو زرو یو بت جوړ کړ. بیا خلکو وویل: «ای اسراییلو، دا زمونږ خدای دی چې مونږ یې د مصر څخه راوویستلو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_4.mp3', '', 1761754199, 1761754199),
(43183, 'Exodus 32:5', 'Exodus', 32, 5, 'بیا هارون د هغه طلایي خوسي په مخکې د قربانۍ یو ځای جوړ کړ او اعلان یې وکړ: «سبا به څښتن ته د درناوي کولو په خاطر اختر وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_5.mp3', '', 1761754199, 1761754199),
(43184, 'Exodus 32:6', 'Exodus', 32, 6, 'نو بله ورځ خلک وختي پاڅېدل او سوځېدونکې نذرانې یې قرباني کړې او د سلامتۍ نذرانې یې وړاندې کړې. بیا هغوی دومره وخوړل او وڅښل چې په مستۍ او عیاشۍ کې ګډا وکړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_6.mp3', '', 1761754199, 1761754199),
(43185, 'Exodus 32:7', 'Exodus', 32, 7, 'بیا څښتن موسی ته وویل: «همدا اوس لاندې ښکته شه، ځکه چې ستا خلک چې تا له مصر څخه راوویستل، فاسد شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_7.mp3', '', 1761754199, 1761754199),
(43186, 'Exodus 32:8', 'Exodus', 32, 8, 'هغوی له هغې لارې څخه چې ما ورته ښودلې ده، ګرځېدلي دي او د ځان دپاره یې د طلایي خوسي په شکل یو بت جوړ کړی دی او سجده ورته کوي. هغه ته یې قربانۍ وړاندې کړې دي او داسې وایي چې ای اسراییلو، دا زمونږ هغه خدای دی چې مونږ یې له مصر څخه راوویستلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_8.mp3', '', 1761754199, 1761754199),
(43187, 'Exodus 32:9', 'Exodus', 32, 9, 'څښتن موسی ته وویل: «زه پوهېږم چې دا سرزوري او سرکښه خلک دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_9.mp3', '', 1761754199, 1761754199),
(43188, 'Exodus 32:10', 'Exodus', 32, 10, 'اوس ته ما مه منع کوه. زه هغوی ته په قهر یم او غواړم چې هغوی له منځه یوسم. بیا به ستا او ستا د اولادې څخه یو لوی قوم جوړ کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_10.mp3', '', 1761754199, 1761754199),
(43189, 'Exodus 32:11', 'Exodus', 32, 11, 'خو موسی خپل څښتن خدای ته زارۍ وکړې او ویې ویل: «څښتنه، ته ولې په خپل قوم باندې چې په خپل قوي مټ سره دې له مصر څخه راوویست، دومره په قهر کېږې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_11.mp3', '', 1761754199, 1761754199),
(43190, 'Exodus 32:12', 'Exodus', 32, 12, 'مصریان ولې ووایي چې تا خپل قوم د دې دپاره له مصر څخه راوویست چې په غرونو کې یې ووژنې او د ځمکې له مخ څخه یې ورک کړې؟ د خپل سخت قهر څخه تېر شه، خپله اراده بدله کړه او په خپل قوم باندې دا افت مه نازلوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_12.mp3', '', 1761754199, 1761754199),
(43191, 'Exodus 32:13', 'Exodus', 32, 13, 'خپل خدمتګاران ابراهیم، اسحاق او یعقوب در په یاد کړه چې تا ورته په خپل ذات باندې دا قسم خوړلی ؤ: زه به ستاسو اولاده د اسمان د ستورو په شان زیاته کړم او ستاسو اولادې ته به هغه ټوله ځمکه ورکړم چې ما د هغوی سره لوظ کړی دی او هغه ځمکه به تر ابده پورې د هغوی ملکیت وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_13.mp3', '', 1761754199, 1761754199),
(43192, 'Exodus 32:14', 'Exodus', 32, 14, 'نو څښتن خپله اراده بدله کړه او په خپل قوم باندې یې هغه افت نازل نه کړ چې هغوی ته یې خبرداری ورکړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_14.mp3', '', 1761754199, 1761754199),
(43193, 'Exodus 32:15', 'Exodus', 32, 15, 'موسی بېرته له غره څخه راښکته شو او د تیږو هغه دوه لوحې چې په دواړو خواو باندې یې د خدای حکمونه لیکل شوي وو، په لاس کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_15.mp3', '', 1761754199, 1761754199),
(43194, 'Exodus 32:16', 'Exodus', 32, 16, 'خدای په خپله هغه لوحې جوړې کړې وې او په هغو باندې یې حکمونه لیکلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_16.mp3', '', 1761754199, 1761754199),
(43195, 'Exodus 32:17', 'Exodus', 32, 17, 'کله چې یوشع د خلکو د چیغو اواز واورېده، هغه موسی ته وویل: «د کمپ څخه د جګړې اواز راځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_17.mp3', '', 1761754199, 1761754199),
(43196, 'Exodus 32:18', 'Exodus', 32, 18, 'موسی په ځواب کې وویل: «دا د بري یا د ماتې اواز نه دی، بلکې دا د سندرې اواز دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_18.mp3', '', 1761754199, 1761754199),
(43197, 'Exodus 32:19', 'Exodus', 32, 19, 'کله چې موسی کمپ ته نژدې شو او هغه خوسی او د خلکو نڅا یې ولیدله، نو ډېر په قهر شو او لوحې یې وغورځولې او هغه یې د غره په لمن کې ټوټې ټوټې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_19.mp3', '', 1761754199, 1761754199),
(43198, 'Exodus 32:20', 'Exodus', 32, 20, 'موسی هغه خوسی چې هغوی جوړ کړی ؤ، راواخیست او په اور کې یې وسوځاوه. بیا یې هغه د پوډرو په شان میده میده کړ او د اوبو سره یې ګډ کړل او په اسراییلیانو باندې یې وڅښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_20.mp3', '', 1761754199, 1761754199),
(43199, 'Exodus 32:21', 'Exodus', 32, 21, 'موسی هارون ته وویل: «دغو خلکو تا سره څه کړي دي چې په دومره لویه ګناه باندې دې اخته کړل؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_21.mp3', '', 1761754199, 1761754199),
(43200, 'Exodus 32:22', 'Exodus', 32, 22, 'هارون په ځواب کې وویل: «زما باداره، مه په قهرېږه، ته دا خلک پېژنې چې د بدو کارونو سره څومره شوق لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_22.mp3', '', 1761754199, 1761754199),
(43201, 'Exodus 32:23', 'Exodus', 32, 23, 'هغوی ماته وویل: مونږ نه پوهېږو چې په دې موسی باندې چې مونږ یې له مصر څخه راوویستلو څه وشول، نو مونږ ته یو خدای جوړ کړه چې لارښوونه راته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_23.mp3', '', 1761754199, 1761754199),
(43202, 'Exodus 32:24', 'Exodus', 32, 24, 'نو ما هغوی ته وویل: هرڅوک چې د سرو زرو ګاڼې لري هغه دې راوباسي. بیا هغوی ماته سره زر راکړل او ما هغه په اور کې واچول او دا خوسی ورڅخه راووت!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_24.mp3', '', 1761754199, 1761754199),
(43203, 'Exodus 32:25', 'Exodus', 32, 25, 'موسی ولیدل چې هارون دا خلک په خپل سر پریښي وو، نو هغوی د خپلو دښمنانو د خندا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_25.mp3', '', 1761754199, 1761754199),
(43204, 'Exodus 32:26', 'Exodus', 32, 26, 'نو موسی د کمپ د دروازې په خوله کې ودرېده او داسې غږ یې وکړ: «هرڅوک چې د څښتن په خوا وي، ماته دې راشي!» نو ټول لاویان د هغه په شاوخوا راټول شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_26.mp3', '', 1761754199, 1761754199),
(43205, 'Exodus 32:27', 'Exodus', 32, 27, 'بیا موسی هغوی ته وویل: «د اسراییلو څښتن خدای حکم کوي چې هرڅوک دې خپله توره د ځان سره واخلي او په کمپ کې دې له دې دروازې څخه تر بلې دروازې پورې لاړ شي او خپل ورونه، ملګري او ګاونډیان دې ووژني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_27.mp3', '', 1761754199, 1761754199),
(43206, 'Exodus 32:28', 'Exodus', 32, 28, 'لاویانو د موسی امر په ځای کړ او په هغه ورځ یې نژدې درې زره کسان ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_28.mp3', '', 1761754199, 1761754199),
(43207, 'Exodus 32:29', 'Exodus', 32, 29, 'بیا موسی لاویانو ته وویل: «تاسو نن څښتن ته وقف شوي یئ، ځکه چې خپل ورونه او زامن مو ووژل، نو څښتن تاسو ته خپل برکت درکړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_29.mp3', '', 1761754199, 1761754199),
(43208, 'Exodus 32:30', 'Exodus', 32, 30, 'بله ورځ موسی خلکو ته وویل: «تاسو لویه ګناه کړې ده. خو اوس به زه بیا څښتن ته غره ته وروخېژم، کېدای شي چې زه وکولای شم د خدای څخه ستاسو د ګناهونو دپاره بخښنه وغواړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_30.mp3', '', 1761754199, 1761754199),
(43209, 'Exodus 32:31', 'Exodus', 32, 31, 'نو موسی بېرته څښتن ته ورغی او ویې ویل: «دغه قوم لویه ګناه کړې ده او د ځانونو دپاره یې د سرو زرو خدای جوړ کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_31.mp3', '', 1761754199, 1761754199),
(43210, 'Exodus 32:32', 'Exodus', 32, 32, 'خو اوس د هغوی ګناه وبخښه. که چېرې دا کار نه کوې، بیا زما نوم د هغه کتاب څخه چې د خپل قوم د خلکو نومونه دې په کې لیکلي دي، لېرې کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_32.mp3', '', 1761754199, 1761754199);